create(context) {
        // Match the same predicate `buildLinkIndex` uses to keep validated-by links
        // (isTestFile: .test./.spec./__tests__/…), so a linkable test can't escape
        // the rule on a naming variant.
        if (!isTestFile(toPosix(context.filename))) {
            return {};
        }
        const options = context.options[0] ?? {};
        const specsRoot = options.specsRoot ?? context.cwd;
        const roots = options.roots ?? ["specs", "adrs"];
        if (!corpusExists(specsRoot, roots)) {
            warnMissingCorpusOnce(specsRoot, roots);
            return {};
        }
        const relPath = toPosix(path.relative(specsRoot, context.filename));
        const corpus = {
            entry: getIndex(specsRoot, roots).get(relPath),
            relPath,
            roots,
        };
        return {
            CallExpression: (node) => reportUnlinked(context, node, corpus),
        };
    }

create(context) {
        const max = context.options[0]?.max ?? 1;
        const openTests = [];
        return {
            CallExpression(node) {
                if (isTestCall(node)) {
                    openTests.push({ node, count: 0 });
                    return;
                }
                if (isExpectRootCall(node) && openTests.length > 0) {
                    openTests[openTests.length - 1].count += 1;
                }
            },
            "CallExpression:exit"(node) {
                if (!isTestCall(node)) {
                    return;
                }
                const { count } = openTests.pop();
                if (count > max) {
                    context.report({
                        node,
                        messageId: "tooManyExpects",
                        data: { count, max },
                    });
                }
            },
        };
    }

create(context) {
        const subject = subjectOf(context.filename);
        if (!subject) {
            return {};
        }
        const firstPartyScopes = context.options[0]?.firstPartyScopes ?? [];
        let importsSubject = false;
        function recordImport(source) {
            importsSubject ||=
                source !== null && loadsRealSubject(source, firstPartyScopes);
        }
        return {
            ImportDeclaration: (node) => recordImport(staticImportSource(node)),
            ImportExpression: (node) => recordImport(dynamicImportSource(node)),
            "Program:exit"(node) {
                if (importsSubject) {
                    return;
                }
                context.report({
                    node,
                    loc: { line: 1, column: 0 },
                    messageId: "noSubjectImport",
                    data: { subject },
                });
            },
        };
    }
